//! 🧪️ Actual child-node receiving preserves old field semantics within original caller opportunities.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation,close_original_retained_step};
use semio_framework_value::{RetireOwned,ToValue};
fn clock()->Option<u64>{Some(1000)}
fn caller()->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(97146),Generation(17),RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:128*1024*1024,maximum_capacity_bytes:256*1024*1024,maximum_release_bytes:512*1024*1024,maximum_depth:4096},clock,1500,32768)}
fn native<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result.unwrap()}
fn close(mut work:NodeWork,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant){
 work.begin_close();for turn in 0..10000{if work.terminal_is_empty(){break}native(caller,decoder,g,|cx|cx.with_original_retirement(|cx|{let d=work.close_demands(g.maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|work.close_step(grant))?;Ok(())}));assert!(turn+1<10000)}assert!(work.terminal_is_empty());drop(work);
 while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(g.maximum_copy_bytes)?;decoder.close_on_source(cx)?;Ok(())})).unwrap();}
}
fn pump(work:&mut NodeWork,node:&Node,cx:&mut StepContext<'_>)->Result<Option<NodeOutput>,OriginalTurnFailure>{for _ in 0..512{let before=(cx.fuel_remaining(),cx.retained_progress());if let Some(output)=work.step(node,cx)?{return Ok(Some(output))}if cx.should_yield()||cx.is_cancelled()||before==(cx.fuel_remaining(),cx.retained_progress()){break}}Ok(None)}
fn node(case:&serde_json::Value)->Node{use semio_s_artifact_stdio_semio_flow::schema::snapshot::FlowParam;Node{id:case["id"].as_str().unwrap().into(),kind:case["kind"].as_str().unwrap().into(),label:case["label"].as_str().unwrap().into(),params:case["params"].as_array().unwrap().iter().map(|p|FlowParam{key:p["key"].as_str().unwrap().into(),value:p["value"].as_str().unwrap().into()}).collect(),position:Default::default()}}
#[test]
fn original_child_node_fields_match_genuine_converter_defaults_and_200_call_custody(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("📁️cases.json")).unwrap();
 for(items,copy,calls)in[(1,4096,10000),(512,32768,200)]{for case in fixture["cases"].as_array().unwrap(){
  let node=node(case);let expected=crate::schema::widget_from_node(&node);let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let g=RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:copy,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:4096};native(&mut caller,&mut decoder,g,|_|Ok(()));let mut work=NodeWork::new();let mut output=None;
  for turn in 0..calls{let before=(work.phase,work.scan,work.index);assert!(native(&mut caller,&mut decoder,RetainedCloneGrant{maximum_items:0,..g},|cx|pump(&mut work,&node,cx)).is_none());assert_eq!((work.phase,work.scan,work.index),before);assert_eq!(caller.receipt(),Default::default());output=native(&mut caller,&mut decoder,g,|cx|pump(&mut work,&node,cx));if output.is_some(){break}assert!(turn+1<calls,"node {} exhausted original opportunity",node.kind)}
  let output=output.unwrap();assert_eq!(output.widget,expected);assert_eq!(output.layout_id,node.id);if let Some(golden)=case.get("expected"){let actual:serde_json::Value=output.widget.to_value().into();assert_eq!(&actual,golden)}work.restore_output(output);expected.retire_cold();close(work,&mut caller,&mut decoder,g);caller.retire(g);
 }}
 for stop in [0,1,7,17,50]{let node=node(&fixture["cases"][0]);let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:4096};native(&mut caller,&mut decoder,g,|_|Ok(()));let mut work=NodeWork::new();for _ in 0..stop{if let Some(output)=native(&mut caller,&mut decoder,g,|cx|pump(&mut work,&node,cx)){work.restore_output(output);break}}caller.cancel().cancel_now();let before=(work.phase,work.scan,work.index);assert!(native(&mut caller,&mut decoder,g,|cx|pump(&mut work,&node,cx)).is_none());assert_eq!((work.phase,work.scan,work.index),before);close(work,&mut caller,&mut decoder,g);caller.retire(g);}
}
